style.css:
@-moz-document domain("youtube.com") {
:root {
    --my-star-black: #050505;
    --my-star-dark: #242424;
    --my-star-silver: #eeeeee;
    --my-star-glow: #777777;
  }

  /* replace YouTube logo */
  ytd-topbar-logo-renderer #logo-icon {
    position: relative !important;
    width: 42px !important;
    height: 42px !important;
    overflow: visible !important;
  }

  /* hide original logo */
  ytd-topbar-logo-renderer #logo-icon svg {
    opacity: 0 !important;
  }

  /* glossy black star */
  ytd-topbar-logo-renderer #logo-icon::before {
    content: "★" !important;
    position: absolute !important;
    inset: -5px !important;
    display: grid !important;
    place-items: center !important;
    font-size: 43px !important;
    background: linear-gradient(
      145deg,
      #ffffff,
      #555555,
      #050505,
      #292929,
      #000000
    ) !important;
    background-clip: text !important;
    -webkit-background-clip: text !important;
    color: transparent !important;
    filter: drop-shadow(0 0 5px #777777) !important;
  }

  /* silver swirl */
  ytd-topbar-logo-renderer #logo-icon::after {
    content: "〰" !important;
    position: absolute !important;
    inset: 7px 0 0 0 !important;
    display: grid !important;
    place-items: center !important;
    color: #eeeeee !important;
    font-size: 19px !important;
    transform: rotate(-35deg) !important;
  }
}
